package br.com.admeclesial.interfaces.rest.catequese;
import br.com.admeclesial.application.catequese.*; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/turmas-catequese")
public class TurmaCatequeseRestController { private final TurmaCatequeseApplicationService service; public TurmaCatequeseRestController(TurmaCatequeseApplicationService s){service=s;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public TurmaCatequeseResponse criar(@Valid @RequestBody TurmaCatequeseRequest r){return service.criar(r);} @PutMapping("/{uuid}") public TurmaCatequeseResponse atualizar(@PathVariable UUID uuid,@Valid @RequestBody TurmaCatequeseRequest r){return service.atualizar(uuid,r);} @GetMapping("/{uuid}") public TurmaCatequeseResponse buscar(@PathVariable UUID uuid){return service.buscar(uuid);} @GetMapping public List<TurmaCatequeseResponse> listar(){return service.listar();} @GetMapping("/por-etapa") public List<TurmaCatequeseResponse> porEtapa(@RequestParam UUID etapaUuid){return service.listarPorEtapa(etapaUuid);} }
